mapper.select:
SELECT /* getProfileStats */ TARGET.USER_NUMB , COALESCE(READSTATS.TOTAL_READ_BOOK_CNT, 0) AS TOTAL_READ_BOOK_CNT , COALESCE(FOLLOWINGSTATS.FOLLOWING_CNT, 0) AS FOLLOWING_CNT , COALESCE(FOLLOWERSTATS.FOLLOWER_CNT, 0) AS FOLLOWER_CNT , COALESCE(LIKESTATS.RECEIVED_LIKE_CNT, 0) AS RECEIVED_LIKE_CNT FROM ( SELECT #{userNumb} AS USER_NUMB ) TARGET LEFT JOIN ( SELECT REPORT.USER_NUMB , COUNT(*) AS TOTAL_READ_BOOK_CNT FROM TM_REPORT REPORT WHERE REPORT.REPT_STAT = #{reportStatDone} AND REPORT.USER_NUMB = #{userNumb}
AND REPORT.PUBC_YSNO = #{pubcYsno}
GROUP BY REPORT.USER_NUMB ) READSTATS ON READSTATS.USER_NUMB = TARGET.USER_NUMB LEFT JOIN ( SELECT FOLLOW.USER_NUMB , COUNT(*) AS FOLLOWING_CNT FROM TB_FOLLOW FOLLOW WHERE FOLLOW.USER_NUMB = #{userNumb} AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = FOLLOW.FLOW_NUMB) OR (B.USER_NUMB = FOLLOW.FLOW_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) ) GROUP BY FOLLOW.USER_NUMB ) FOLLOWINGSTATS ON FOLLOWINGSTATS.USER_NUMB = TARGET.USER_NUMB LEFT JOIN ( SELECT FOLLOW.FLOW_NUMB AS USER_NUMB , COUNT(*) AS FOLLOWER_CNT FROM TB_FOLLOW FOLLOW WHERE FOLLOW.FLOW_NUMB = #{userNumb} AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = FOLLOW.USER_NUMB) OR (B.USER_NUMB = FOLLOW.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) ) GROUP BY FOLLOW.FLOW_NUMB ) FOLLOWERSTATS ON FOLLOWERSTATS.USER_NUMB = TARGET.USER_NUMB LEFT JOIN ( SELECT REPORT.USER_NUMB , COUNT(*) AS RECEIVED_LIKE_CNT FROM TB_LIKEXX LIKES INNER JOIN TM_USERXM LIKEUSER ON LIKEUSER.USER_NUMB = LIKES.USER_NUMB AND LIKEUSER.USER_STAT = #{userStatActive} INNER JOIN TM_REPORT REPORT ON REPORT.REPT_NUMB = LIKES.TAGT_NUMB WHERE LIKES.TAGT_TYPE = #{likeTargetReport} AND REPORT.USER_NUMB = #{userNumb} AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = LIKES.USER_NUMB) OR (B.USER_NUMB = LIKES.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) )
AND REPORT.PUBC_YSNO = #{pubcYsno}
GROUP BY REPORT.USER_NUMB ) LIKESTATS ON LIKESTATS.USER_NUMB = TARGET.USER_NUMB

SELECT /* getFollowingList */
FROM TB_FOLLOW FL INNER JOIN TM_USERXM U ON U.USER_NUMB = FL.FLOW_NUMB LEFT JOIN TM_FILEXM F ON F.FILE_NUMB = U.PROF_NUMB LEFT JOIN TB_FOLLOW USERFOLLOW ON USERFOLLOW.USER_NUMB = #{loginUserNumb} AND USERFOLLOW.FLOW_NUMB = U.USER_NUMB LEFT JOIN TB_FOLLOW REVERSEFOLLOW ON REVERSEFOLLOW.USER_NUMB = U.USER_NUMB AND REVERSEFOLLOW.FLOW_NUMB = #{loginUserNumb} WHERE FL.USER_NUMB = #{userNumb}
AND INSTR(U.USER_NICK, #{keyword}) > 0
AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = U.USER_NUMB) OR (B.USER_NUMB = U.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) ) ORDER BY CASE WHEN USERFOLLOW.USER_NUMB IS NOT NULL AND REVERSEFOLLOW.USER_NUMB IS NOT NULL THEN 0 ELSE 1 END , CASE WHEN U.USER_NUMB = #{loginUserNumb} THEN 0 ELSE 1 END , FL.REGI_DATE DESC , U.USER_NUMB DESC LIMIT #{pageOffset}, #{pageLimit}

SELECT /* getFollowerList */
FROM TB_FOLLOW FL INNER JOIN TM_USERXM U ON U.USER_NUMB = FL.USER_NUMB LEFT JOIN TM_FILEXM F ON F.FILE_NUMB = U.PROF_NUMB LEFT JOIN TB_FOLLOW USERFOLLOW ON USERFOLLOW.USER_NUMB = #{loginUserNumb} AND USERFOLLOW.FLOW_NUMB = U.USER_NUMB LEFT JOIN TB_FOLLOW REVERSEFOLLOW ON REVERSEFOLLOW.USER_NUMB = U.USER_NUMB AND REVERSEFOLLOW.FLOW_NUMB = #{loginUserNumb} WHERE FL.FLOW_NUMB = #{userNumb}
AND INSTR(U.USER_NICK, #{keyword}) > 0
AND NOT EXISTS ( SELECT 1 FROM TB_USBLOC B WHERE (B.USER_NUMB = #{loginUserNumb} AND B.BLOC_NUMB = U.USER_NUMB) OR (B.USER_NUMB = U.USER_NUMB AND B.BLOC_NUMB = #{loginUserNumb}) ) ORDER BY CASE WHEN USERFOLLOW.USER_NUMB IS NOT NULL AND REVERSEFOLLOW.USER_NUMB IS NOT NULL THEN 0 ELSE 1 END , CASE WHEN U.USER_NUMB = #{loginUserNumb} THEN 0 ELSE 1 END , FL.REGI_DATE DESC , U.USER_NUMB DESC LIMIT #{pageOffset}, #{pageLimit}











SELECT /* getLikeTargetAccessCnt */ COUNT(*)
  FROM (
        SELECT REPORT.REPT_NUMB AS TAGT_NUMB
          FROM TM_REPORT REPORT
         WHERE #{tagtType} = #{targetReport}
           AND REPORT.REPT_NUMB = #{tagtNumb}
           AND EXISTS (
                SELECT 1
                  FROM TM_USERXM OWNERX
                 WHERE OWNERX.USER_NUMB = REPORT.USER_NUMB
                   AND OWNERX.USER_STAT = #{userStatActive}
           )
           AND (REPORT.USER_NUMB = #{loginUserNumb}
                OR (REPORT.PUBC_YSNO = #{commYes} AND REPORT.REPT_STAT != #{reportStatRead})
                OR EXISTS (
                    SELECT 1
                      FROM TB_CLPART PART
                      JOIN TM_CLRNDX ROUNDX
                        ON ROUNDX.CLUB_NUMB = PART.CLUB_NUMB
                       AND ROUNDX.ROND_NUMB = PART.ROND_NUMB
                       AND ROUNDX.ROND_STAT = #{roundCompleted}
                      JOIN TB_CLMEMX VIEWER
                        ON VIEWER.CLUB_NUMB = PART.CLUB_NUMB
                       AND VIEWER.USER_NUMB = #{loginUserNumb}
                       AND VIEWER.MEMB_STAT = #{memberActive}
                     WHERE PART.REPT_NUMB = REPORT.REPT_NUMB
                ))
         UNION ALL
        SELECT USERX.USER_NUMB AS TAGT_NUMB
          FROM TM_USERXM USERX
         WHERE USERX.USER_STAT = #{userStatActive}
           AND ((#{tagtType} = #{targetProfile} AND USERX.PROF_NUMB = #{tagtNumb})
                OR (#{tagtType} = #{targetBackground} AND USERX.BGIM_NUMB = #{tagtNumb}))
         UNION ALL
        SELECT REPLY.REPL_NUMB AS TAGT_NUMB
          FROM TB_REPLXX REPLY
         WHERE #{tagtType} = #{targetReply}
           AND REPLY.REPL_NUMB = #{tagtNumb}
           AND REPLY.DELT_YSNO = #{commNo}
           AND (
                (REPLY.TAGT_TYPE = #{targetReport} AND EXISTS (
                    SELECT 1
                     FROM TM_REPORT REPORT
                     WHERE REPORT.REPT_NUMB = REPLY.TAGT_NUMB
                       AND EXISTS (
                            SELECT 1
                              FROM TM_USERXM OWNERX
                             WHERE OWNERX.USER_NUMB = REPORT.USER_NUMB
                               AND OWNERX.USER_STAT = #{userStatActive}
                       )
                       AND (REPORT.USER_NUMB = #{loginUserNumb}
                            OR (REPORT.PUBC_YSNO = #{commYes} AND REPORT.REPT_STAT != #{reportStatRead})
                            OR EXISTS (
                                SELECT 1
                                  FROM TB_CLPART PART
                                  JOIN TM_CLRNDX ROUNDX
                                    ON ROUNDX.CLUB_NUMB = PART.CLUB_NUMB
                                   AND ROUNDX.ROND_NUMB = PART.ROND_NUMB
                                   AND ROUNDX.ROND_STAT = #{roundCompleted}
                                  JOIN TB_CLMEMX VIEWER
                                    ON VIEWER.CLUB_NUMB = PART.CLUB_NUMB
                                   AND VIEWER.USER_NUMB = #{loginUserNumb}
                                   AND VIEWER.MEMB_STAT = #{memberActive}
                                 WHERE PART.REPT_NUMB = REPORT.REPT_NUMB
                            ))
                ))
                OR EXISTS (
                    SELECT 1
                      FROM TM_USERXM USERX
                     WHERE USERX.USER_STAT = #{userStatActive}
                       AND ((REPLY.TAGT_TYPE = #{targetProfile} AND USERX.PROF_NUMB = REPLY.TAGT_NUMB)
                            OR (REPLY.TAGT_TYPE = #{targetBackground} AND USERX.BGIM_NUMB = REPLY.TAGT_NUMB))
                )
           )
       ) TARGETX
